#!/usr/bin/env node
/**
 * Differential test vectors for the portal message contents (internal security review, Phase 0).
 *
 *   node scripts/security/portal-vectors.mjs          writes the three generated files
 *   node scripts/security/portal-vectors.mjs --check  exits 1 if any of them is out of date
 *
 * The reference here is an independent restatement with node:crypto only: sha256ToField of
 * abi.encodeWithSignature("mint_to_private(uint256)", amount) and of
 * abi.encodeWithSignature("withdraw(address,uint256,address)", recipient, amount, caller).
 * The same vectors are then checked against:
 *   Solidity   contracts/portal/AztecMessaging.sol   test/foundry/Differential.t.sol
 *   TypeScript lib/portal/receivers.ts               test/unit/portal/content-vectors.test.ts
 *   Noir       contracts/aztec/portal_token/src/content.nr   generated block in src/test.nr
 * so the three implementations must give the same bytes. Amounts stay below 2^128 (u128 on Aztec).
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const sha = (b) => createHash('sha256').update(b).digest();
const field = (b) => '0x00' + sha(b).subarray(0, 31).toString('hex');
const word = (x) => Buffer.from(BigInt(x).toString(16).padStart(64, '0'), 'hex');
const MINT = Buffer.from('8b3af5e8', 'hex');
const WITHDRAW = Buffer.from('69328dec', 'hex');
const mint = (amount) => field(Buffer.concat([MINT, word(amount)]));
const withdraw = (r, amount, c) => field(Buffer.concat([WITHDRAW, word(r), word(amount), word(c)]));

// Deterministic pseudo-random values: sha256("hl/vectors/<n>").
const prng = (n, bits) => BigInt('0x' + sha(Buffer.from(`hl/vectors/${n}`)).toString('hex')) % (1n << BigInt(bits));
const U128 = (1n << 128n) - 1n;
const amounts = [1n, 2n, 999n, 1000n, 25000000n, 10n ** 18n, (1n << 64n) - 1n, 1n << 64n, U128 - 1n, U128];
for (let i = 0; i < 14; i++) amounts.push(prng(i, 128) || 1n);
const addrs = ['0x0000000000000000000000000000000000000001', '0x000000000000000000000000000000000000beef', '0xffffffffffffffffffffffffffffffffffffffff'];
for (let i = 0; i < 9; i++) addrs.push('0x' + prng(100 + i, 160).toString(16).padStart(40, '0'));

const mints = amounts.map((a) => ({ amount: a.toString(), content: mint(a) }));
const withdraws = addrs.map((r, i) => {
  const amount = amounts[(i * 7) % amounts.length];
  const caller = i % 3 === 0 ? '0x0000000000000000000000000000000000000000' : addrs[(i + 4) % addrs.length];
  return { recipient: r, amount: amount.toString(), caller, content: withdraw(r, amount, caller) };
});

const json = JSON.stringify({ note: 'Generated by scripts/security/portal-vectors.mjs. Do not edit.', mints, withdraws }, null, 2) + '\n';

const sol = `// SPDX-License-Identifier: MIT
// Generated by scripts/security/portal-vectors.mjs. Do not edit.
pragma solidity ^0.8.24;

library PortalVectors {
    function mintAmounts() internal pure returns (uint256[${mints.length}] memory a) {
${mints.map((m, i) => `        a[${i}] = ${m.amount};`).join('\n')}
    }

    function mintContents() internal pure returns (bytes32[${mints.length}] memory c) {
${mints.map((m, i) => `        c[${i}] = ${m.content};`).join('\n')}
    }

    function withdrawRecipients() internal pure returns (address[${withdraws.length}] memory r) {
${withdraws.map((w, i) => `        r[${i}] = address(uint160(${BigInt(w.recipient)}));`).join('\n')}
    }

    function withdrawAmounts() internal pure returns (uint256[${withdraws.length}] memory a) {
${withdraws.map((w, i) => `        a[${i}] = ${w.amount};`).join('\n')}
    }

    function withdrawCallers() internal pure returns (address[${withdraws.length}] memory c) {
${withdraws.map((w, i) => `        c[${i}] = address(uint160(${BigInt(w.caller)}));`).join('\n')}
    }

    function withdrawContents() internal pure returns (bytes32[${withdraws.length}] memory c) {
${withdraws.map((w, i) => `        c[${i}] = ${w.content};`).join('\n')}
    }
}
`;

const BEGIN = '// BEGIN GENERATED VECTORS (scripts/security/portal-vectors.mjs)';
const END = '// END GENERATED VECTORS';
const noirBlock = `${BEGIN}
#[test]
unconstrained fn contents_match_the_differential_vectors() {
${mints.map((m) => `    assert(mint_to_private_content(${m.amount}) == ${m.content});`).join('\n')}
${withdraws.map((w) => `    assert(withdraw_content(${w.recipient}, ${w.amount}, ${w.caller}) == ${w.content});`).join('\n')}
}
${END}`;

const NOIR_FILE = 'contracts/aztec/portal_token/src/test.nr';
const noirSrc = readFileSync(NOIR_FILE, 'utf8');
const start = noirSrc.indexOf(BEGIN);
const end = noirSrc.indexOf(END);
const noirOut = start >= 0 && end > start
  ? noirSrc.slice(0, start) + noirBlock + noirSrc.slice(end + END.length)
  : noirSrc.replace(/\s*$/, '\n\n') + noirBlock + '\n';

const outputs = [
  ['test/vectors/portal-content.json', json],
  ['test/foundry/vectors/PortalVectors.sol', sol],
  [NOIR_FILE, noirOut],
];
if (process.argv.includes('--check')) {
  const stale = outputs.filter(([p, c]) => { try { return readFileSync(p, 'utf8') !== c; } catch { return true; } }).map(([p]) => p);
  if (stale.length) { console.error('Out of date: ' + stale.join(', ') + '\nRun node scripts/security/portal-vectors.mjs'); process.exit(1); }
  console.log(`Vectors current: ${mints.length} mint, ${withdraws.length} withdraw.`);
} else {
  for (const [p, c] of outputs) { mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, c); }
  console.log(`Wrote ${outputs.map(([p]) => p).join(', ')}`);
}
